ALTER TABLE public.finance_contracts ADD COLUMN billing_category text CHECK(billing_category IN ('30_dias','7_dias','pushes'));
ALTER TABLE public.finance_workflow ADD COLUMN due_on date;
CREATE OR REPLACE FUNCTION public.intranet_classify_finance(p_type text,p_id uuid,p_category text,p_due date DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.intranet_can_access('financeiro') OR NOT public.can_write_finance(auth.uid()) THEN RAISE EXCEPTION 'Sem acesso financeiro' USING ERRCODE='42501'; END IF;
IF p_type NOT IN ('evento','anuncio') OR p_category NOT IN ('30_dias','7_dias','pushes') THEN RAISE EXCEPTION 'Classificação inválida'; END IF;
IF (p_type='evento' AND NOT EXISTS(SELECT 1 FROM public.submissions WHERE id=p_id AND deleted_at IS NULL AND promotion_choice='highlight')) OR (p_type='anuncio' AND NOT EXISTS(SELECT 1 FROM public.ads WHERE id=p_id AND (ad_type='pago' OR product_id IS NOT NULL))) THEN RAISE EXCEPTION 'Item financeiro não encontrado'; END IF;
INSERT INTO public.finance_contracts(item_type,item_id,commercial_type,updated_by,billing_category) VALUES(p_type,p_id,'paid',auth.uid(),p_category) ON CONFLICT(item_type,item_id) DO UPDATE SET billing_category=excluded.billing_category,updated_by=auth.uid(),updated_at=now();
INSERT INTO public.finance_workflow(item_type,item_id,due_on) VALUES(p_type,p_id,p_due) ON CONFLICT(item_type,item_id) DO UPDATE SET due_on=excluded.due_on,updated_at=now(); END $$;
REVOKE ALL ON FUNCTION public.intranet_classify_finance(text,uuid,text,date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.intranet_classify_finance(text,uuid,text,date) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.intranet_finance_metrics(p_days integer DEFAULT 30) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT public.intranet_can_access('financeiro') THEN RAISE EXCEPTION 'Sem acesso financeiro' USING ERRCODE='42501'; END IF; IF p_days NOT IN (7,30,90) THEN RAISE EXCEPTION 'Período inválido'; END IF;
RETURN jsonb_build_object('categories',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM(SELECT coalesce(c.billing_category,'sem_classificacao') name,sum(p.amount_cents) value FROM public.payment_records p LEFT JOIN public.finance_contracts c USING(item_type,item_id) WHERE p.settled_at>=now()-make_interval(days=>p_days) GROUP BY 1)t),'overdue',(SELECT count(*) FROM public.finance_workflow w WHERE w.due_on<(now() AT TIME ZONE 'America/Sao_Paulo')::date AND w.status='pending' AND NOT EXISTS(SELECT 1 FROM public.payment_records p WHERE p.item_type=w.item_type AND p.item_id=w.item_id) AND NOT EXISTS(SELECT 1 FROM public.finance_contracts c WHERE c.item_type=w.item_type AND c.item_id=w.item_id AND c.commercial_type IN ('courtesy','barter'))),'unclassified',(SELECT count(*) FROM public.finance_workflow WHERE due_on IS NULL)); END $$;
REVOKE ALL ON FUNCTION public.intranet_finance_metrics(integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.intranet_finance_metrics(integer) TO authenticated,service_role;